# SEO Optimization for Astro

## Meta Tags

### Pattern: Essential Meta Tags

```astro
---
import BaseHead from '../components/ui/BaseHead.astro';

interface Props {
  title: string;
  description: string;
  canonicalUrl?: string;
}

const { title, description, canonicalUrl } = Astro.props;
---

<!-- BaseHead component handles core meta tags -->
<BaseHead title={title} description={description} />

<!-- Additional SEO meta tags -->
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<meta charset="UTF-8" />
<meta name="robots" content="index, follow" />
<meta name="language" content="French" />

{canonicalUrl && <link rel="canonical" href={canonicalUrl} />}
```

### Pattern: Open Graph Tags

```astro
---
interface Props {
  title: string;
  description: string;
  ogImage?: string;
  ogType?: 'website' | 'article' | 'profile';
  url: string;
}

const {
  title,
  description,
  ogImage,
  ogType = 'website',
  url
} = Astro.props;
---

<!-- ✅ Good: Complete Open Graph meta tags -->
<meta property="og:title" content={title} />
<meta property="og:description" content={description} />
<meta property="og:type" content={ogType} />
<meta property="og:url" content={url} />
{ogImage && <meta property="og:image" content={ogImage} />}
<meta property="og:image:alt" content={title} />
<meta property="og:site_name" content="Your Blog" />

<!-- Twitter Card tags -->
<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:title" content={title} />
<meta name="twitter:description" content={description} />
{ogImage && <meta name="twitter:image" content={ogImage} />}
```

### Anti-pattern: Missing Meta Tags

```astro
<!-- ❌ Bad: No Open Graph or Twitter tags -->
<head>
  <title>{title}</title>
  <meta name="description" content={description} />
</head>
```

## Article Meta Tags

### Pattern: Blog Post SEO

```astro
---
import type { CollectionEntry } from 'astro:content';

interface Props {
  post: CollectionEntry<'blog'>;
}

const { post } = Astro.props;
const { title, description, pubDate, updatedDate, tags, heroImage } = post.data;
const url = `https://yourdomain.com/blog/${post.slug}`;
---

<!-- Article-specific meta tags -->
<meta property="article:published_time" content={pubDate.toISOString()} />
{updatedDate && (
  <meta
    property="article:modified_time"
    content={updatedDate.toISOString()}
  />
)}

<!-- Keywords/tags -->
{tags?.map((tag) => (
  <meta property="article:tag" content={tag} key={tag} />
))}

<!-- Author -->
<meta property="article:author" content="Author Name" />

<!-- Image and social -->
<meta property="og:title" content={title} />
<meta property="og:description" content={description} />
<meta property="og:image" content={`https://yourdomain.com${heroImage}`} />
<meta property="og:type" content="article" />
<meta property="og:url" content={url} />

<!-- Canonical URL -->
<link rel="canonical" href={url} />
```

## Structured Data (Schema.org)

### Pattern: Article Schema

```astro
---
import { AUTHOR_CONFIG, SITE_CONFIG } from '../config/site';
import type { CollectionEntry } from 'astro:content';

interface Props {
  post: CollectionEntry<'blog'>;
}

const { post } = Astro.props;
const { title, description, pubDate, updatedDate, heroImage } = post.data;
---

<!-- ✅ Good: Structured data for search engines -->
<script type="application/ld+json" set:html={JSON.stringify({
  '@context': 'https://schema.org',
  '@type': 'BlogPosting',
  headline: title,
  description: description,
  datePublished: pubDate.toISOString(),
  dateModified: updatedDate?.toISOString() || pubDate.toISOString(),
  image: {
    '@type': 'ImageObject',
    url: `${SITE_CONFIG.url}${heroImage}`,
    width: 1200,
    height: 675,
  },
  author: {
    '@type': 'Person',
    name: AUTHOR_CONFIG.name,
    url: SITE_CONFIG.url,
  },
  publisher: {
    '@type': 'Organization',
    name: SITE_CONFIG.title,
    logo: {
      '@type': 'ImageObject',
      url: `${SITE_CONFIG.url}/logo.png`,
      width: 200,
      height: 60,
    },
  },
})} />
```

### Pattern: Organization Schema

```astro
---
const organizationSchema = {
  '@context': 'https://schema.org',
  '@type': 'Organization',
  name: 'Your Organization',
  url: 'https://yourdomain.com',
  logo: 'https://yourdomain.com/logo.png',
  description: 'Organization description',
  sameAs: [
    'https://www.twitter.com/yourprofile',
    'https://www.linkedin.com/company/yourprofile',
  ],
  contactPoint: {
    '@type': 'ContactPoint',
    contactType: 'Customer Service',
    email: 'contact@yourdomain.com',
  },
};
---

<script type="application/ld+json" set:html={JSON.stringify(organizationSchema)} />
```

## Sitemaps

### Pattern: Generate Sitemap

```typescript
// src/pages/sitemap.xml.ts
import { getCollection } from 'astro:content';
import { SITE_CONFIG } from '../config/site';

export async function GET() {
  const pages = [
    { url: '/', lastmod: new Date().toISOString() },
    { url: '/about', lastmod: new Date().toISOString() },
    { url: '/blog', lastmod: new Date().toISOString() },
  ];

  const blog = await getCollection('blog');
  const blogPages = blog.map((post) => ({
    url: `/blog/${post.slug}`,
    lastmod: post.data.updatedDate?.toISOString() || post.data.pubDate.toISOString(),
  }));

  const allPages = [...pages, ...blogPages];

  const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${allPages.map(({ url, lastmod }) => `
  <url>
    <loc>${SITE_CONFIG.url}${url}</loc>
    <lastmod>${lastmod}</lastmod>
    <changefreq>${url === '/blog' ? 'weekly' : 'monthly'}</changefreq>
    <priority>${url === '/' ? '1.0' : '0.8'}</priority>
  </url>
`).join('')}
</urlset>`;

  return new Response(sitemap, {
    headers: { 'Content-Type': 'application/xml' },
  });
}
```

## RSS Feeds

### Pattern: Generate RSS Feed

```typescript
// src/pages/rss.xml.js
import rss from '@astrojs/rss';
import { getCollection } from 'astro:content';
import { SITE_CONFIG } from '../config/site';

export async function GET(context) {
  const blog = await getCollection('blog');

  return rss({
    title: SITE_CONFIG.title,
    description: SITE_CONFIG.description,
    site: context.site,
    items: blog.map((post) => ({
      title: post.data.title,
      pubDate: post.data.pubDate,
      description: post.data.description,
      link: `/blog/${post.slug}/`,
    })),
    customData: `<language>fr</language>`,
  });
}
```

## Heading Hierarchy

### Pattern: Proper H1-H6 Structure

```astro
---
// ✅ Good: One H1 per page, logical hierarchy
interface Props {
  title: string;
  description?: string;
}

const { title, description } = Astro.props;
---

<article>
  <!-- One H1 per page -->
  <h1>{title}</h1>

  {description && <p class="lead">{description}</p>}

  <!-- Sections with H2 -->
  <section>
    <h2>Section One</h2>

    <!-- Subsections with H3 -->
    <h3>Subsection</h3>
    <p>Content...</p>
  </section>
</article>
```

### Anti-pattern: Multiple H1s

```astro
<!-- ❌ Bad: Multiple H1 elements -->
<h1>Main Title</h1>
<h1>Another Title</h1>

<!-- ❌ Bad: Skipping levels (H1 → H3) -->
<h1>Title</h1>
<h3>Subtitle</h3>
```

## Canonical URLs

### Pattern: Canonical URL Implementation

```astro
---
interface Props {
  canonicalUrl?: string;
}

const { canonicalUrl } = Astro.props;
const defaultCanonical = `https://yourdomain.com${Astro.url.pathname}`;
---

<!-- ✅ Good: Specify canonical URL to prevent duplicate content -->
<link rel="canonical" href={canonicalUrl || defaultCanonical} />
```

## SEO Checklist

- [ ] One H1 per page (never skip heading levels)
- [ ] Title tag: 50-60 characters
- [ ] Meta description: 150-160 characters
- [ ] Open Graph tags (og:title, og:description, og:image)
- [ ] Twitter Card tags (twitter:card, twitter:image)
- [ ] Canonical URL specified
- [ ] Structured data (Schema.org) for content type
- [ ] Sitemap.xml generated and valid
- [ ] RSS feed implemented
- [ ] Internal linking strategy
- [ ] Mobile-friendly (responsive design)
- [ ] Fast page load (Core Web Vitals)
- [ ] Descriptive alt text on images
- [ ] Focus on user intent (E-E-A-T)

